// Idempotency key pattern — safe retries in distributed systems
const { randomUUID } = require('node:crypto');

class NonRetryableError extends Error {}

// ── CLIENT SIDE ──────────────────────────────────────────────
// Create the key ONCE per logical operation, then reuse it on every retry.
// A random UUID is fine (Stripe recommends v4); what breaks dedup is minting a
// NEW key per attempt. Persist it with the pending operation (or derive it from
// a business id such as `checkout:${cartId}`) so even a client restart reuses it.
async function createOrderWithRetry(cartId, body, send, maxAttempts = 5) {
  const idempotencyKey = `checkout:${cartId}`;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await send({ idempotencyKey, body });
      if (res.status < 300) return res.body;
      if (res.status !== 429 && res.status < 500) {
        throw new NonRetryableError(`HTTP ${res.status}`); // 4xx: retrying won't help
      }
      throw new Error(`HTTP ${res.status}`);               // 5xx/429: transient
    } catch (err) {
      if (err instanceof NonRetryableError || attempt === maxAttempts) throw err;
      const cap = Math.min(100 * 2 ** attempt, 10_000);    // exponential backoff
      await new Promise((r) => setTimeout(r, Math.random() * cap)); // "full jitter"
    }
  }
}

// ── SERVER SIDE ──────────────────────────────────────────────
// Production: a DB table with a UNIQUE key column, or Redis SET key NX EX 86400.
const keys = new Map(); // key -> { state: 'in_progress' | 'done', response }
let ordersCreated = 0;

async function handleCreateOrder({ idempotencyKey, body }) {
  if (!idempotencyKey) return { status: 400, body: { error: 'Idempotency-Key required' } };
  const existing = keys.get(idempotencyKey);
  if (existing?.state === 'done') return existing.response;          // replay
  if (existing) return { status: 409, body: { error: 'in progress' } }; // concurrent dup

  keys.set(idempotencyKey, { state: 'in_progress' }); // claim BEFORE side effects
  try {
    const response = { status: 201, body: { orderId: ++ordersCreated, ...body } };
    keys.set(idempotencyKey, { state: 'done', response });
    return response;
  } catch (err) {
    keys.delete(idempotencyKey); // failed before any effect: allow a clean retry
    throw err;
  }
}

// ── DEMO: the first response is "lost", the client retries with the same key ──
(async () => {
  let calls = 0;
  const flakyNetwork = async (req) => {
    const res = await handleCreateOrder(req);
    if (++calls === 1) throw new Error('timeout'); // server did the work, reply lost
    return res;
  };
  const order = await createOrderWithRetry('cart-7', { amount: 50 }, flakyNetwork);
  console.log(order, 'orders created:', ordersCreated); // { orderId: 1, amount: 50 } orders created: 1
})();

// Quorum writes and reads: N=3 replicas, W=2, R=2  =>  W + R > N (4 > 3)
const replicas = [
  { id: 'node-a', delayMs: 10, data: new Map() },
  { id: 'node-b', delayMs: 20, data: new Map() },
  { id: 'node-c', delayMs: 300, data: new Map() }, // slow replica
];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let version = 0; // stand-in for a per-key version (real systems: vector/hybrid clocks)

// Resolve as soon as `needed` promises have fulfilled (in ARRIVAL order)
function firstN(promises, needed) {
  return new Promise((resolve, reject) => {
    const results = []; let failed = 0;
    for (const p of promises) {
      p.then((v) => { results.push(v); if (results.length === needed) resolve(results); },
             () => { if (++failed > promises.length - needed) reject(new Error('quorum unreachable')); });
    }
  });
}

async function quorumWrite(key, value, W = 2) {
  const entry = { value, version: ++version };
  const acks = await firstN(replicas.map(async (r) => {
    await sleep(r.delayMs);
    r.data.set(key, entry);
    return r.id;
  }), W);
  console.log(`write acked by ${acks.join(', ')} (W=${W})`); // node-c finishes later
}

async function quorumRead(key, R = 2, from = replicas) {
  const replies = await firstN(from.map(async (r) => {
    const entry = r.data.get(key); // replica reads its local state now...
    await sleep(r.delayMs / 10);   // ...and the reply travels back
    return { id: r.id, entry };
  }), R);
  // Highest version wins; a real store would also read-repair stale replicas
  const best = replies.filter((x) => x.entry).sort((a, b) => b.entry.version - a.entry.version)[0];
  console.log('read replies:', replies.map((x) => `${x.id}=${x.entry?.value ?? '∅'}`).join(' '));
  return best?.entry.value ?? null;
}

(async () => {
  await quorumWrite('user:42:name', 'Alice');
  // Worst case for overlap: ask the slow replica plus one that DID ack.
  // Any 2 of 3 replicas must include at least one of the 2 that acked.
  const name = await quorumRead('user:42:name', 2, [replicas[2], replicas[1]]);
  console.log('read:', name); // read replies: node-b=Alice node-c=∅  ->  read: Alice
})();

// Circuit breaker + exponential backoff with jitter

class CircuitBreaker {
  constructor({ failureThreshold = 5, successThreshold = 2, timeout = 30000 } = {}) {
    this.state = 'CLOSED';      // CLOSED | OPEN | HALF_OPEN
    this.failures = 0;
    this.successes = 0;
    this.failureThreshold = failureThreshold;
    this.successThreshold = successThreshold;
    this.timeout = timeout;
    this.nextAttempt = Date.now();
  }

  async call(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() < this.nextAttempt) {
        const err = new Error('Circuit OPEN — fast-fail, protecting downstream');
        err.code = 'CIRCUIT_OPEN';
        throw err;
      }
      this.state = 'HALF_OPEN';
      this.successes = 0;
      console.log('Circuit HALF_OPEN — testing downstream...');
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  onSuccess() {
    this.failures = 0;
    if (this.state === 'HALF_OPEN') {
      this.successes++;
      if (this.successes >= this.successThreshold) {
        this.state = 'CLOSED';
        this.successes = 0;
        console.log('Circuit CLOSED — downstream healthy');
      }
    }
  }

  onFailure() {
    this.failures++;
    if (this.state === 'HALF_OPEN' || this.failures >= this.failureThreshold) {
      this.state = 'OPEN';
      this.nextAttempt = Date.now() + this.timeout;
      console.log(`Circuit OPEN — will retry in ${this.timeout}ms`);
    }
  }
}

// Retry with exponential backoff + jitter
async function withRetry(fn, maxAttempts = 5) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      // Never retry into an open circuit — that defeats the breaker
      if (err.code === 'CIRCUIT_OPEN' || attempt === maxAttempts) throw err;
      const base = Math.min(100 * 2 ** attempt, 30000);  // cap at 30s
      const jitter = Math.random() * base * 0.3;          // add 0–30% random extra
      const delay = Math.round(base + jitter);
      console.log(`Attempt ${attempt} failed. Retrying in ${delay}ms...`);
      await new Promise(r => setTimeout(r, delay));
    }
  }
}

// Compose circuit breaker with retry
const breaker = new CircuitBreaker({ failureThreshold: 3, timeout: 10000 });

async function callUserService(userId) {
  return withRetry(() =>
    breaker.call(async () => {
      const res = await fetch(`https://user-service/users/${userId}`, {
        signal: AbortSignal.timeout(2000), // every remote call needs a timeout
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`); // fetch does not throw on 5xx
      return res.json();
    })
  );
}
